var x = theRoot.varToString("CUR_FOL").split("/"),
    y = theRoot.varToString("CUR_FOL_NOM").split("/");

x.pop();
y.pop();

var newX = x.join("/"),
	newFolderName = y.join("/");

if ( theRoot.varToString("PLA") == "drive" ) {
	theRoot.setVar("CUR_FOL", newX == "" ? "root" : newX );
	theRoot.setVar("CUR_FOL_NOM", newFolderName == "" ? "folder2" : newFolderName );

} else {
	theRoot.setVar("CUR_FOL", newX == "" ? "/" : newX );
}

theRoot.dataView().updateControls();
